816	// ════════════════════════════════════════════════════════════════════════
817	//  BACKWARD over one TOKEN TILE. Assumes dectc_forward_tile ran for THIS tile
818	//  (scratch + DecActs X-inputs populated). Fork B: computes dX via wgmma and
819	//  WRITES the dY output-adjoints to DecActs (dY_qkv/dY_a/dY_ff0/dY_ff2/
820	//  dY_logits) + dh0 for P2's output-stationary dW — it does NOT touch the
821	//  weight dW here. ACCUMULATES the 10 LN-vector grads (γ/β) into the per-CTA
822	//  LN-vec partials `lnvec` [kNumLnVec × d] (deterministic single-owner-per-j).
823	//  `B` is the full batch (CE mean scale). Mirrors dec_backward_sample.
824	//
825	//  dqkv/dctx/dgact intermediates use the fp32 `work` buffer + a second fp32
826	//  buffer `work2` (caller passes both, each [nrows×dff]); dh (running adjoint)
827	//  is the dedicated scratch.dh.
828	// ════════════════════════════════════════════════════════════════════════
829	__device__ void dectc_backward_tile(
830	        const DecWeights& w, int g0, int nrows, int B, const DecActs& acts,
831	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
832	        float* __restrict__ lnvec, float* __restrict__ work2,
833	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
834	    const int nsamp = nrows / dec::kSeq;
835	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
836	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
837	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
838	    for (int li = 0; li < dec::kLayers; ++li) {
839	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
840	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
841	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
842	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
843	    }
844	    float* gn_normw = lnvec + (int64_t)8 * dec::kD;
845	    float* gn_normb = lnvec + (int64_t)9 * dec::kD;
846	
847	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B, overwrite logits.
848	    //    head bwd: dY_logits[si] = dlogits (the head dW operand); dhn = dlogits@out_w.
849	    //    final-norm bwd: dh_last (last position only) → scratch.dh (zero others). ──
850	    // First zero scratch.dh for the whole tile (only last positions get grad).
851	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
852	    __syncthreads();
853	    for (int si = 0; si < nsamp; ++si) {
854	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
855	        const int gs = si_global(g0, si);
856	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
857	        int tgt = tgt_ids[gs];
858	        // softmax of cached logits.
859	        float lmax = -CUDART_INF_F;
860	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
861	        lmax = dec_block_max(lmax, red);
862	        float es = 0.0f;
863	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
864	        es = dec_block_sum(es, red);
865	        float inv_es = 1.0f / es;
866	        // dlogits → overwrite lg, AND write to dY_logits[gs] (bf16, head dW operand).
867	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
868	            float smo = __expf(lg[o] - lmax) * inv_es;
869	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
870	            lg[o] = dl;
871	            acts.dY_logits[(int64_t)gs * dec::kVocab + o] = __float2bfloat16(dl);
872	        }
873	        __syncthreads();
874	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j]  (head dX), feature-parallel → dh row rlast.
875	        // Then final-norm bwd of that single row → scratch.dh[rlast].
876	        // Use fnx cache (xhat) + fni (inv). Accumulate norm γ/β. (head dW is P2.)
877	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
878	            float dhn = 0.0f;
879	            for (int o = 0; o < dec::kVocab; ++o)
880	                dhn += lg[o] * w.out_w[(int64_t)o * dec::kD + j];
881	            // final-norm bwd needs the row-reduce of dxhat; stash dhn into work row rlast.
882	            sc.work[(int64_t)rlast * dec::kD + j] = dhn;
883	        }
884	        __syncthreads();
885	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only last pos contributes.)
886	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
887	            float dhn = sc.work[(int64_t)rlast * dec::kD + j];
888	            float xh = sc.fnx[(int64_t)rlast * dec::kD + j];
889	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
890	        }
891	        __syncthreads();
892	        // LN dx (single row): dxhat=dhn*norm_w; reduce; dh[rlast] = inv*(dxhat-(sda+xhat*sdax)/d).
893	        {
894	            const float* dyr = sc.work + (int64_t)rlast * dec::kD;
895	            const float* xhr = sc.fnx + (int64_t)rlast * dec::kD;
896	            float sda = 0.0f, sdax = 0.0f;
897	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
898	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
899	            }
900	            sda = dec_block_sum(sda, red); sdax = dec_block_sum(sdax, red);
901	            float iv = sc.fni[rlast];
902	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
903	                float dxhat = dyr[j] * w.norm_w[j];
904	                sc.dh[(int64_t)rlast * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
905	            }
906	            __syncthreads();
907	        }
908	    }
909	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only last positions nonzero).
910	
911	    // ── per-layer backward (reverse). dh is the running adjoint (grad wrt the
912	    //    layer's n2 output). All fwd intermediates are in scratch/DecActs (NO
913	    //    recompute). ──
914	    for (int li = dec::kLayers - 1; li >= 0; --li) {
915	        const DecWeights::Layer& L = w.layer[li];
916	        // n2 bwd: dh → dr2 (work fp32), accumulate n2 γ/β. xhat=n2x[li], inv=n2i[li].
917	        dectc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
918	        // r2 = x1 + ff2 → dx1 = dr2 (residual), dff2 = dr2. dff2 → dY_ff2 acts (bf16).
919	        // dx1 starts as dr2 (copy into work2), the FFN path adds to it.
920	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
921	            work2[idx] = sc.work[idx];   // dx1 := dr2 (residual part)
922	            acts.dY_ff2[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // dff2
923	        }
924	        __syncthreads();
925	        // ff2 dX: dgact = dff2 @ ff2_w  (N=dff, K=d). fp32 → tw? need a [nrows,dff] buffer.
926	        //   Use sc.work (currently dr2, no longer needed — dx1 saved in work2, dff2 in acts).
927	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * dec::kD, L.ff2_w,
928	                                           sc.work, dec::kDff, dec::kD, sA, sB);  // dgact [nrows,dff]
929	        __syncthreads();
930	        // dff0 = dgact * gelu'(ff0pre) → dY_ff0 acts (bf16) AND keep fp32 in sc.work for dX.
931	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
932	            float dff0 = sc.work[idx] * dec_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
933	            sc.work[idx] = dff0;
934	            acts.dY_ff0[li][(int64_t)g0 * dec::kDff + idx] = __float2bfloat16(dff0);
935	        }
936	        __syncthreads();
937	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32
938	        //   → sc.x1 (free now — fwd x1 consumed); then add to work2.
939	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * dec::kDff, L.ff0_w,
940	                                           sc.x1, /*Kin=*/dec::kD, /*Nout=*/dec::kDff, sA, sB);  // dx1_ffn [nrows,d]
941	        __syncthreads();
942	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
943	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
944	        __syncthreads();
945	        // n1 bwd: dx1 (work2) → dr1 (work), accumulate n1 γ/β. xhat=n1x[li], inv=n1i[li].
946	        dectc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
947	        // r1 = x_in + a → da = dr1 (out_proj output adjoint), dx_in = dr1 (residual).
948	        // SAVE the residual dr1 into sc.dh NOW (dh is free — its grad was consumed into
949	        // dr2 at the top of this layer); attention bwd will overwrite work2. Then add the
950	        // in_proj dX path to it. da → dY_a acts (bf16, out_proj dW operand).
951	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
952	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1  (saved across attn bwd)
953	            acts.dY_a[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
954	        }
955	        __syncthreads();
956	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
957	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * dec::kD, L.out_w,
958	                                           sc.work, dec::kD, dec::kD, sA, sB);  // dctx
959	        __syncthreads();
960	        // attention bwd: (qkv[li], attn[li], dctx=work) → dqkv [nrows,3d] fp32 into
961	        //   work2 (3d=384 ≤ dff=512, fits). Then → dY_qkv acts (bf16, in_proj dW operand).
962	        dectc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
963	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x)
964	            acts.dY_qkv[li][(int64_t)g0 * 3 * dec::kD + idx] = __float2bfloat16(work2[idx]);
965	        __syncthreads();
966	        // in_proj dX: dx_in_attn = dqkv @ in_w  (output width Kin=d, contract Nout=3d).
967	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
968	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * dec::kD, L.in_w,
969	                                           sc.work, /*Kin=*/dec::kD, /*Nout=*/3 * dec::kD, sA, sB);  // dx_in_attn
970	        __syncthreads();
971	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
972	            sc.dh[idx] += sc.work[idx];   // dx_in = residual (in dh) + attn path
973	        __syncthreads();
974	    }
975	
976	    // ── embedding bwd: dh = grad wrt h0 [nrows,d]. Write dh0 acts (bf16); the
977	    //    tok/pos owner-scan (P2) reads dh0 by global token row. ──
978	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
979	        acts.dh0[(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.dh[idx]);
980	    __syncthreads();
981	}
