983	// ════════════════════════════════════════════════════════════════════════
984	//  P2 — OUTPUT-STATIONARY dW (the Q2 deliverable). Each of the 9 weight
985	//  matrices dW = dYᵀ @ X (K=T) is split into 64×N output tiles; tile_id %
986	//  nCTA owns each (fixed every step → determinism + L2 warmth). The owner CTA
987	//  contracts the FULL token dimension itself (ascending-t, no float atomics, no
988	//  partials) via the validated dW orientation (tc_gemm_block_unpipelined with
989	//  BOTH operands transposed-staged, MaxAtomsM=1 → one 64×N tile, 64 acc regs/
990	//  thread, no spill). Writes the tile into `grad` (the reduced-grad output).
991	//
992	//  The 9 weights, in dec_layout tensor-index order, with their (dY,X) acts and
993	//  the contraction length K (T for per-position weights, B for the head).
994	// ════════════════════════════════════════════════════════════════════════
995	struct DecDwSpec {
996	    const __nv_bfloat16* dY;   // [K, Nout]
997	    const __nv_bfloat16* X;    // [K, Kin]
998	    int Nout; int Kin; int K;
999	    int grad_off;              // element offset of this weight in `grad`
1000	    const __nv_bfloat16* dY_bias;  // same as dY (bias db = Σ_K dY)
1001	    int bias_off;              // element offset of the bias in `grad`
1002	};
1003	
1004	// Build the 9 specs (called by all CTAs; cheap). T = B*kSeq.
1005	__device__ __forceinline__ void dectc_build_dw_specs(
1006	        const DecActs& acts, int B, int T, DecDwSpec spec[9]) {
1007	    // dec_layout offsets: see kDecOffsets. Weight tensor indices (and bias idx):
1008	    //   L0: in_w=2 (in_b=3), out_w=4 (out_b=5), ff0_w=10 (ff0_b=11), ff2_w=12 (ff2_b=13)
1009	    //   L1: in_w=14(15), out_w=16(17), ff0_w=22(23), ff2_w=24(25)
1010	    //   head: out_w=28 (out_b=29)
1011	    const int wi[9]  = {2,4,10,12, 14,16,22,24, 28};
1012	    const int bi[9]  = {3,5,11,13, 15,17,23,25, 29};
1013	    for (int s = 0; s < 8; ++s) {
1014	        const int li = s / 4, kind = s % 4;
1015	        DecDwSpec& sp = spec[s];
1016	        sp.K = T; sp.grad_off = kDecOffsets[wi[s]]; sp.bias_off = kDecOffsets[bi[s]];
1017	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
1018	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
1019	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
1020	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
1021	        sp.dY_bias = sp.dY;
1022	    }
1023	    DecDwSpec& hd = spec[8];
1024	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
1025	    hd.grad_off = kDecOffsets[28]; hd.bias_off = kDecOffsets[29]; hd.dY_bias = hd.dY;
1026	}
