1028	// Total number of 64×N dW output tiles across the 9 weights (for the tile loop).
1029	template <int N>
1030	__device__ __forceinline__ int dectc_dw_total_tiles(const DecDwSpec spec[9]) {
1031	    int n = 0;
1032	    for (int s = 0; s < 9; ++s)
1033	        n += ((spec[s].Nout + 63) / 64) * ((spec[s].Kin + N - 1) / N);
1034	    return n;
1035	}
1036	
1037	// Run ONE global dW tile `gt` (if it belongs to this CTA): decode (weight, M-atom,
1038	// N-tile), then contract K via the dW GEMM into grad[grad_off]. MaxAtomsM=1.
1039	template <int N>
1040	__device__ __forceinline__ void dectc_dw_run_tile(
1041	        const DecDwSpec spec[9], int gt, float* __restrict__ grad,
1042	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1043	    // Decode gt → (s, m_atom, n_tile).
1044	    int acc = 0, s = 0, m_atom = 0, n_tile = 0;
1045	    for (s = 0; s < 9; ++s) {
1046	        const int ma = (spec[s].Nout + 63) / 64;
1047	        const int nt = (spec[s].Kin + N - 1) / N;
1048	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; break; }
1049	        acc += ma * nt;
1050	    }
1051	    const DecDwSpec& sp = spec[s];
1052	    const int mbase = m_atom * 64;
1053	    const int n0 = n_tile * N;
1054	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1055	    const int k_steps = sp.K / wgs::kWgmmaAtomK;     // K = T or B (must be /16; padded by caller)
1056	    const int Nout = sp.Nout, Kin = sp.Kin;
1057	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1058	    // The engine (tc_gemm_block_unpipelined, mbase0=mbase, m_atoms=1) passes the
1059	    // GLOBAL row m = mbase + mn to srcA/out (it adds mbase0 itself), so the
1060	    // accessors use `m` RAW — adding mbase again would double-count (the selftest
1061	    // passes mbase0=0 and uses m raw; we pass mbase0=mbase and likewise use m raw).
1062	    // A[m=out, k=t] = dY[t,out]  (transposed read); B[n=in, k=t] = X[t,in] (transposed).
1063	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1064	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
1065	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1066	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
1067	    auto out  = [&] (int m, int n, float v) {
1068	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1069	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1070	        mbase, /*m_atoms=*/1, n_real, k_steps, srcA, srcB, out, sA, sB);
1071	}
1072	
1073	// Biases db = Σ_K dY  (per output row). Work-stealing over the 9 weights' rows is
1074	// overkill; instead each CTA strides ALL bias outputs (cheap: ≤ 3d=384 rows × 9).
1075	// Single owner per output element (thread strides global bias-row index) → no atomics.
1076	__device__ __forceinline__ void dectc_dw_biases(
1077	        const DecDwSpec spec[9], float* __restrict__ grad) {
1078	    for (int s = 0; s < 9; ++s) {
1079	        const DecDwSpec& sp = spec[s];
1080	        for (int o = threadIdx.x; o < sp.Nout; o += blockDim.x) {
1081	            float accv = 0.0f;
1082	            for (int k = 0; k < sp.K; ++k) accv += __bfloat162float(sp.dY_bias[(int64_t)k * sp.Nout + o]);
1083	            grad[sp.bias_off + o] = accv;
1084	        }
1085	    }
1086	}
1087	
1088	// ════════════════════════════════════════════════════════════════════════
1089	//  P2 — EMBEDDING owner-scan (tok/pos). dh0 [T,d] (bf16) holds grad wrt h0.
1090	//    tok grad: row r (token id) of tok.weight → owner CTA (r % nCTA); the owner
1091	//    scans ALL T tokens in ascending t, accumulating dh0[t,:] for tokens whose
1092	//    id == r. pos grad: row p → owner; sums dh0[t,:] over t with (t%S)==p.
1093	//    Fixed t-order + single owner per row → deterministic, atomic-free.
1094	//    `tok_ids` is HBM int32 [T]. Writes grad[tok_off..], grad[pos_off..].
1095	// ════════════════════════════════════════════════════════════════════════
1096	__device__ __forceinline__ void dectc_embed_owner_scan(
1097	        const DecActs& acts, const int* __restrict__ tok_ids, int T,
1098	        float* __restrict__ grad, int cta, int nCTA) {
1099	    const int tok_off = kDecOffsets[0];   // tok.weight [V,d]
1100	    const int pos_off = kDecOffsets[1];   // pos.weight [S,d]
1101	    // tok rows owned by this CTA: r in [0,V) with r % nCTA == cta.
1102	    for (int r = cta; r < dec::kVocab; r += nCTA) {
1103	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1104	            float accv = 0.0f;
1105	            for (int t = 0; t < T; ++t)
1106	                if (tok_ids[t] == r) accv += __bfloat162float(acts.dh0[(int64_t)t * dec::kD + j]);
1107	            grad[tok_off + (int64_t)r * dec::kD + j] = accv;
1108	        }
1109	    }
1110	    // pos rows owned by this CTA: p in [0,S) with p % nCTA == cta.
1111	    for (int p = cta; p < dec::kSeq; p += nCTA) {
1112	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1113	            float accv = 0.0f;
1114	            for (int t = 0; t < T; ++t)
1115	                if ((t % dec::kSeq) == p) accv += __bfloat162float(acts.dh0[(int64_t)t * dec::kD + j]);
1116	            grad[pos_off + (int64_t)p * dec::kD + j] = accv;
1117	        }
1118	    }
1119	}
1120	
1121	// ════════════════════════════════════════════════════════════════════════
1122	//  P2 — LN-vector grad reduce. The 10 γ/β grads were accumulated tile-locally
1123	//    into each CTA's lnvec partials [kNumLnVec × d]; sum across CTAs in
1124	//    ASCENDING CTA index (deterministic) into the 10 dec_layout slots of grad.
1125	//    `lnvec_base` is the start of the [nCTA × kLnVecElems] partial region.
1126	// ════════════════════════════════════════════════════════════════════════
1127	__device__ __forceinline__ void dectc_lnvec_reduce(
1128	        const float* __restrict__ lnvec_base, float* __restrict__ grad,
1129	        int nCTA, int cta) {
1130	    // Each CTA reduces a subset of the 10 LN tensors (round-robin by tensor).
1131	    for (int v = cta; v < kNumLnVec; v += nCTA) {
1132	        const int goff = kLnVecTensorIdx[v];
1133	        const int64_t gbase = kDecOffsets[goff];
1134	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1135	            float accv = 0.0f;
1136	            for (int c = 0; c < nCTA; ++c)
1137	                accv += lnvec_base[(int64_t)c * kLnVecElems + (int64_t)v * dec::kD + j];
1138	            grad[gbase + j] = accv;
1139	        }
1140	    }
1141	}
