105	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor
106	// slice at `off` within the flat [m|v|extra] layout. Per-TENSOR fields (the
107	// NeuralGrok psi MLP weights) and all scalars pass through unchanged.
108	template <OptId Opt>
109	__device__ __forceinline__ FusedOptState
110	rebase_state(const FusedOptState& s, int64_t off) {
111	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
112	    if (t.exp_avg)    t.exp_avg    += off;
113	    if (t.exp_avg_sq) t.exp_avg_sq += off;
114	    if (t.ema)        t.ema        += off;
115	    if (t.sam_dir)    t.sam_dir    += off;
116	    if (t.s_track)    t.s_track    += off;
117	    if (t.mu)         t.mu         += off;
118	    if (t.orth)       t.orth       += off;
119	    if (t.smart_grad) t.smart_grad += off;
120	    return t;
121	}
