123	// The L3-REAL decoder megakernel needs the token path + a grad-partial workspace
124	// in addition to the FuseTier::{L1,L3} ABI. We keep it a SEPARATE kernel +
125	// launcher (not folded into fused_megakernel) so the surrogate path is untouched.
126	//
127	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
128	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
129	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
130	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
131	// total == kDecTotalElems == 422755.
132	
133	struct DecoderTokenCtx {
134	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
135	    const int* targets;  // [B]       int32 target ids
136	    int        B;        // batch size (full-batch in the race ≈ 4191)
137	    float*     workspace; // grad partials + loss partials + reduced loss
138	    float*     loss_out;  // device float the kernel writes the mean loss into
139	};
140	
141	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
142	//    threads/CTA. The smem holds ONE DecSampleSmem (≈42 KB, < 48 KB static cap —
143	//    no dynamic-smem opt-in, so the occupancy≥1 guard with dynamicSMemBytes=0 in
144	//    the launcher is unchanged). ────────────────────────────────────────────────
145	// sizes/offsets are NOT host-passed: the per-tensor numel/offset live in the
146	// generated __constant__ tables kDecSizes/kDecOffsets (decoder_layout.cuh), so
147	// the reduce + optimizer phases read them directly. This also lets the host side
148	// (dispatch.cpp) avoid building any layout tensors.
149	template <OptId Opt>
150	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
151	fused_decoder_megakernel(PersistentContext ctx,
152	                         float* __restrict__ params,
153	                         DecoderTokenCtx tok,
154	                         float* __restrict__ grad,        // reduced grad [total]
155	                         float lr, int step, FusedOptState st) {
156	    __shared__ DecSampleSmem sm;
157	    GridBarrier bar = ctx.barrier();
158	    const int cta = blockIdx.x;
159	    const int nCTA = (int)ctx.n_ctas;
160	    const int64_t total = kDecTotalElems;
161	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
162	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
163	
164	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
165	    const int wg = threadIdx.x / 128;
166	    // warp-specialize prims live in sg::sm90::wgs (this file is sg::fused::sm90)
167	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
168	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
169	
170	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
171	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
172	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
173	    bar.sync();   // B0
174	
175	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
176	    DecWeights w = dec_bind(params);
177	    DecGrad g = dec_bind_grad(my_partial);
178	    // Even split with remainder to the low CTAs (contiguous, deterministic).
179	    const int B = tok.B;
180	    const int base = B / nCTA, rem = B % nCTA;
181	    const int b0 = cta * base + (cta < rem ? cta : rem);
182	    const int cnt = base + (cta < rem ? 1 : 0);
183	    const int b1 = b0 + cnt;
184	    __shared__ int tok_s[dec::kSeq];   // this sample's token ids (broadcast)
185	    __shared__ int tgt_s;
186	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
187	    for (int b = b0; b < b1; ++b) {
188	        if (threadIdx.x < dec::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * dec::kSeq + threadIdx.x];
189	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
190	        __syncthreads();
191	        float nll = dec_forward_sample(w, tok_s, tgt_s, &sm);
192	        dec_backward_sample(w, g, tok_s, tgt_s, B, &sm);
193	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
194	        __syncthreads();   // sample boundary: all grad writes done before reuse
195	    }
196	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
197	    bar.sync();   // B1: all CTA partials + loss slots complete
198	
199	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
200	    //    (one task = one parameter tensor; sum its elements across CTAs in
201	    //    ascending CTA index). The summation ORDER (ascending cta) is fixed, so
202	    //    the result is deterministic regardless of which CTA grabs the task. ────
203	    {
204	        __shared__ int task_slot;
205	        TaskQueue q = ctx.queue();
206	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
207	             t = q.next_block(&task_slot)) {
208	            const int n = kDecSizes[t];
209	            const int64_t off = (int64_t)kDecOffsets[t];
210	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
211	                float acc = 0.0f;
212	                // ascending CTA index → fixed fp32 summation order (deterministic).
213	                for (int c = 0; c < nCTA; ++c)
214	                    acc += tok.workspace[(int64_t)c * total + off + i];
215	                grad[off + i] = acc;
216	            }
217	        }
218	    }
219	    // Loss reduction (fp64 ordered) by CTA 0 only — the 1e-5 loss rel-tol is the
220	    // tightest gate; fp32 atomic-summing ~4191 terms can miss it.
221	    if (cta == 0 && threadIdx.x == 0) {
222	        double s = 0.0;
223	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
224	        float mean = (float)(s / (double)B);
225	        *tok.loss_out = mean;
226	    }
227	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
228	
229	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
230	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
231	    st.lr = lr;
232	    {
233	        __shared__ int task_slot;
234	        TaskQueue q = ctx.queue();
235	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
236	             t = q.next_block(&task_slot)) {
237	            const int n = kDecSizes[t];
238	            const int64_t off = (int64_t)kDecOffsets[t];
239	            const FusedOptState ts = rebase_state<Opt>(st, off);
240	            float* __restrict__ p = params + off;
241	            const float* __restrict__ gg = grad + off;
242	            for (int i = threadIdx.x; i < n; i += blockDim.x)
243	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
244	        }
245	    }
246	}
